"""Generate the editable report and PDF from computed evidence."""
from pathlib import Path
import json
import csv
import hashlib
from xml.sax.saxutils import escape
import reportlab
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib.enums import TA_LEFT
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, KeepTogether
from cleaning import ROOT, RULES

def generate(root=ROOT):
 e=root/'evidence'; c=json.loads((e/'full_data_checks.json').read_text()); checks=json.loads((e/'five_record_checks.json').read_text())
 repro=json.loads((e/'reproducibility.json').read_text()) if (e/'reproducibility.json').exists() else {'status':'Not yet tested in two fresh processes'}
 followup_path=root/'validation/followup_verification.json'
 followup=json.loads(followup_path.read_text()) if followup_path.exists() else {}
 expectations=json.loads((root/'validation/expected_records.json').read_text())
 followup_ok=(followup.get('status')=='PASS' and followup.get('expectations_sha256')==hashlib.sha256((root/'validation/expected_records.json').read_bytes()).hexdigest() and followup.get('sample_sha256')==hashlib.sha256((root/'data/sample/coverage_sample.csv').read_bytes()).hexdigest())
 decision_checks={
 'R1':'Check column_audit.csv for source types and whitespace; compare original and sample identifiers for the five cases. IDs are stored as strings.',
 'R2':f"Check exact duplicates ({c['exact_note_duplicates']:,}) separately from conflicting note IDs ({c['conflicting_note_ids']:,}); record 5 shows two identical source rows yielding one qualifying note.",
 'R3':f"Check blank counts and invalid-field counters. Main-feed sentinel exclusions: {c['not_eligible_sentinel']:,}; output_missing.csv records remaining missing first-note times.",
 'R4':'Compare original eligibility and creation timestamps with the cutoff in the five checks; specifically exclude the pre-eligibility note in record 2.',
 'R5':f"Assert output tweetId uniqueness and {c['eligible_posts']:,} eligible rows = {c['merge_rows']:,} output rows; the LEFT JOIN preserves unmatched posts.",
 'R6':f"Report unmatched posts ({c['unmatched_any_note']:,}) separately from posts with no qualifying note ({c['no_qualifying_note_observed']:,}); retain snapshot and interpretation limitations."}
 report_rules=[(a, ('LEFT JOIN eligible requests to usable notes on tweetId, then GROUP BY the unique request key to obtain one row per post. Keep unmatched requests.' if a=='R5' else b),d) for a,b,d in RULES]
 missing=', '.join(c['missing_expected_notes_files']) or 'None of the five expected filenames is missing; aligned snapshot completeness remains unverified.'
 rate='undefined' if c['coverage_rate'] is None else f"{100*c['coverage_rate']:.4f}%"
 sections=[('Community Notes Coverage: Individual Cleaning Report', 'Jiamao Tian | DSO 576 Module 6 | Coverage scope only. This is individual evidence for the group reconciliation, not a claim that the team has reconciled its results.'),
 ('Result and scope',f"Observed coverage in the supplied files: {c['covered_posts']:,} / {c['eligible_posts']:,} = {rate}. Requests with no qualifying note observed: {c['no_qualifying_note_observed']:,}. These are file-based observations, not population estimates. Expected Notes files missing: {missing}"),
 ('1. Vision and analysis question - Done', 'A Community Notes Product Manager must decide where additional note-writing or rating effort should be directed to improve coverage and reduce response time while maintaining broad agreement. This individual assignment prepares the coverage branch only. Among posts eligible for the main note-request feed by the cutoff, how many have at least one observed note created on or after eligibility and by the cutoff? Written notes are not necessarily Helpful or publicly displayed.'),
 ('2. Define one row - Done', 'Raw requests: one post and its feed eligibility fields, with tweetId expected unique. Raw Notes: one note, with noteId expected unique; multiple notes per tweetId are valid. Final coverage_cleaned.csv: exactly one eligible post per tweetId. All final analysis columns are included in the sample.'),
 ('3. Preserve the source - Unresolved', 'Original files are read only from data/raw. source_manifest.json records exact filenames, byte counts and SHA-256 hashes. Source supplied by the student: X Community Notes public data, https://communitynotes.x.com/guide/en/under-the-hood/download-data . Original download date/version was not supplied; preparation date is 2026-10-04, not a retrieval date. Reproduction requires the same source files, not a new live download. Obtain the original snapshot from the student for instructor review; current public downloads may differ.'),
 ('4. Columns and types - Done',f"All raw fields are read as strings. tweetId and noteId remain strings, avoiding floating-point rounding. Selected timestamps require positive integer millisecond syntax and are converted to numeric/UTC derived fields. Invalid Notes IDs after exact deduplication: {c['invalid_note_ids']:,} (including negative/sentinel IDs, which cannot identify a valid post). Invalid Notes timestamps after exact deduplication: {c['invalid_note_time']:,}. Missing/invalid main-feed eligibility excluding -1: {c['invalid_or_missing_eligibility']:,}. Invalid request IDs: {c['invalid_request_id']:,}. Failed required fields are excluded from the analysis, not repaired by guessing. See column_audit.csv for every original column."),
 ('5. Standardize text - Done', 'The audited ID and selected timestamp fields have zero outer-whitespace values in the submitted snapshot, so trimming changes no values in these fields. Example: original tweetId 1253353708961902596 remains 1253353708961902596 in the cleaned sample. Identifiers are strings; meaningful prose, capitalization and leading zeros are preserved. No case-normalization or spelling correction is needed for the analytical fields. See column_audit.csv. The -1 eligibility interpretation is a missing/eligibility rule, not an example of text standardization.'),
 ('6. Duplicates - Done', f"Raw Notes rows: {c['raw_notes']:,}; fully identical repeated rows removed: {c['exact_note_duplicates']:,}; distinct remaining conflicting noteIds: {c['conflicting_note_ids']:,}, involving {c['conflicting_note_rows']:,} rows. Conflicting IDs are excluded altogether. Exact duplicate request rows: {c['exact_request_duplicates']:,}; repeated request IDs after exact deduplication: {c['repeated_request_ids']:,}. Conflicting request IDs stop the run for review. Repeated tweetIds in Notes are retained."),
 ('7. Missing data - Done', f"Original blank counts appear in column_audit.csv; missing counts for every output column appear in output_missing.csv. Optional text blanks are retained in the preserved source and do not exclude posts. {c['not_eligible_sentinel']:,} main-feed -1 values mean not eligible; they are not filled with dates. The final cohort contains no missing tweetId or eligibility_ms. first_qualifying_note_ms remains blank for {c['no_qualifying_note_observed']:,} posts because no qualifying note was observed. The derived count is zero for those posts; this does not establish absence on X."),
 ('8. Suspicious values - Done', f"Fixed analytical cutoff: {c['cutoff_utc']}. This is a deliberate common calculation boundary near the end of the request data, not a verified export timestamp. Eligibility after cutoff: {c['eligibility_after_cutoff']:,}; usable notes after cutoff: {c['notes_after_cutoff']:,}. Those are outside the analysis window, not inherently erroneous. Pre-eligibility notes attached to cohort posts: {c['pre_eligibility_notes']:,}; retain them in the observed-note count but exclude them from qualifying-note counts. Recent requests (<7 days follow-up): {c['recent_posts']:,}; flag them rather than delete them."),
 ('9. Verify merges - Done',f"Join key: tweetId. Requests-to-notes is one-to-many; aggregate to post level before using the result. Input usable notes: {c['usable_notes']:,}, covering {c['unique_note_tweets']:,} unique posts. Eligible request rows: {c['eligible_posts']:,}; output rows: {c['merge_rows']:,}. Requests matching any usable note: {c['matched_any_note']:,}; matching none: {c['unmatched_any_note']:,}. Note tweetIds outside the eligible request cohort: {c['note_tweets_without_eligible_request']:,}. Final tweetId uniqueness and unchanged denominator are asserted."),
 ('10. Reconcile changes - Done', f"Notes reconciliation: {c['raw_notes']:,} raw = {c['exact_note_duplicates']:,} exact duplicates removed + {c['invalid_or_conflicting_note_rows']:,} invalid/conflicting rows excluded + {c['usable_notes']:,} usable notes. Requests: {c['raw_requests']:,} raw -> {c['eligible_posts']:,} eligible post-level output. Request exclusions are determined by exact duplicates, invalid keys, -1/missing/invalid eligibility and cutoff. Counters for these reasons are provided separately and may overlap if a future file has several problems on the same row. Coverage count {c['covered_posts']:,} plus no qualifying note observed {c['no_qualifying_note_observed']:,} equals denominator {c['eligible_posts']:,}."),
 ('11. Check calculations - Done',f"Numerator counts distinct eligible posts with qualifying_note_count > 0, not total notes. Denominator is all {c['eligible_posts']:,} valid eligible posts by cutoff, including unmatched posts. There are {c['qualifying_notes']:,} qualifying notes. The >=7-day follow-up subset contains {c['at_least_7_days_posts']:,} posts and {c['at_least_7_days_covered']:,} observed covered posts; this is a sensitivity description, not a corrected estimate. No classification grouping is used, because unanswered posts have no note classification. Missing first-note times are not converted to zero time."),
 ('12. Five original-to-cleaned record checks - '+('Done' if followup_ok else 'Unresolved'), 'Five independent raw-to-output checks from the original run pass. However, the cases were selected after cleaning; the original run does not establish that case-specific expectations were written beforehand. validation/expected_records.json now fixes expectations and individual reasons for a follow-up verification. This is a disclosed later validation, not a reconstruction of the original chronology. Follow-up verification status: '+('PASS' if followup_ok else 'PENDING: run python3 verify_submission.py')+'. The follow-up reopens all original source files, verifies their SHA-256 hashes, computes the five outcomes independently, and compares them with fixed expectations and the saved cleaned output. Student review is still required.'),
 ('13. Reproducibility - '+('Done' if repro.get('status')=='PASS' else 'Unresolved'), 'Run python reproduce.py from the project root. It launches cleaning.py in two fresh Python processes, hashes all deterministic evidence/output files, and asserts equality. Recorded result: '+str(repro)+'. The notebook can also be restarted and run all; it calls the same reproducibility workflow.'),
 ('14. Remaining limitations - Done', 'All five expected Notes files were included in the local run. Even all five filenames do not prove complete, contemporaneous exports or include deleted notes. Unmatched records are observational, not verified coverage gaps. Recent requests have less follow-up. Main-feed eligibility is distinct from other feed eligibility, and -1 in the main feed is not overridden by an API feed. This assignment measures note writing only, not helpfulness, public display, misinformation truth, broad agreement, or response time. Source retrieval metadata and redistribution terms remain unverified. Group reconciliation and GitHub upload remain student/team actions.'),
 ('Cleaning decision log', '\n'.join(f'{a}: {b} Reason: {d} Verification: {decision_checks[a]}' for a,b,d in report_rules)),
 ('Rule revision log', 'Before implementation, the uploaded original files were audited. The initial idea to concatenate Notes was refined to remove fully identical cross-file duplicates, because the original audit found them. The simplistic any-note match was replaced with the Phase 1 temporal definition (eligibility <= creation <= cutoff). The initial test used four uploaded Notes files. The subsequent local run included all five expected Notes files. During submission review, the R5 description was corrected to match the existing LEFT JOIN followed by GROUP BY implementation. This was a documentation correction; cleaning.py and the analytic results were not changed. Case-specific fixed expectations were added for a disclosed follow-up check after the initial run.'),
 ('Sample selection', 'Up to 50 actual cleaned post rows: first include the five difficult/representative cases, then select remaining rows without replacement using random_state=576. All columns of the final analysis dataset are included. This is an inspection sample, not a representative basis for the reported full-input checks. No raw note text, author participant IDs, source links or suggestion prose is included in the final analysis schema.'),
 ('Codex verification response', 'Suggestion checked: remove fully identical cross-file Notes rows, while retaining distinct notes for the same post. Verification: an independent csv.DictReader pass rereads the raw TSVs and hashes all fields for each selected row, instead of relying on the cleaning SQL table. For tweetId 1253353708961902596, noteId 2082124719525130520 appears in notes-00001.tsv at record 7 and notes-00002.tsv at record 4, with creation time 1785252350875 after eligibility 1785245256671. The raw-row comparison identifies the second occurrence as an exact duplicate. Expected qualifying count is 1, and the saved cleaned count is 1. As a countercheck, tweetId 1701209223000916034 has five distinct qualifying notes and retains count 5. Conclusion: exact-row removal avoids double counting without discarding valid distinct notes. Evidence: five_record_checks.json and the optional follow-up verification. These checks are code-assisted; the report does not claim an unperformed manual inspection by the student.'),
 ('Submission and team reconciliation', 'The assignment has two submission descriptions: a ZIP with report/code/README/data evidence, and a final GitHub/group instruction specifying an individual branch with .py, notebook and sample plus one reconciled group checklist PDF. This package supports both. Use this report as the individual evidence; the group should reconcile differences and submit its own final PDF. Do not label this report as a completed team reconciliation. The module handout did not provide separate decision-log or Codex-response templates beyond the checklist; explicit sections are supplied here.')]
 for i,x in enumerate(checks,1):
  fixed=next(v for v in expectations['cases'] if v['tweetId']==x['tweetId'])
  originals='\n'.join(f"Original note: noteId {v['noteId']}; createdAtMillis {v['createdAtMillis']}; source {v['file']}, record {v['line']}; exact duplicate {v['exact_duplicate']}." for v in x['original_notes']) or 'Original notes: no matching note found in the supplied files.'
  sections.append((f"Record check {i}: {x['case']}",f"tweetId: {x['tweetId']}; original eligibility ms: {x['original_eligibility_ms']}.\n{originals}\nFixed follow-up expected count: {fixed['qualifying_note_count']}; saved actual count: {x['actual_qualifying_note_count']}. Expected first qualifying ms: {fixed['first_qualifying_note_ms']}; actual: {x['actual_first_note_ms']}. Counts and earliest times match: {x['expected_qualifying_note_count']==x['actual_qualifying_note_count'] and x['expected_first_note_ms']==x['actual_first_note_ms']}.\nReason: {fixed['reason']}"))
 metadata_path=root/'SUBMISSION_METADATA.json'
 metadata=json.loads(metadata_path.read_text()) if metadata_path.exists() else {}
 sections.append(('GitHub submission information', 'Branch: '+metadata.get('branch','jessica-module6-cleaning')+'\nBranch URL: '+metadata.get('branch_url','https://github.com/jiamaotian/misinformation-analysis/tree/jessica-module6-cleaning')+'\nCode commit ID: '+(metadata.get('commit_id') or 'PENDING - fill after successful commit and push')+'\nThe commit identifies the submitted code/evidence version. This report may be regenerated in a subsequent documentation commit. A branch URL alone does not establish a successful push.'))
 (root/'REPORT.md').write_text('\n\n'.join('# '+h+'\n\n'+t for h,t in sections)+'\n',encoding='utf-8')
 fontdir=Path(reportlab.__file__).parent/'fonts'
 pdfmetrics.registerFont(TTFont('Vera',str(fontdir/'Vera.ttf')))
 pdfmetrics.registerFont(TTFont('VeraBold',str(fontdir/'VeraBd.ttf')))
 styles=getSampleStyleSheet(); styles['BodyText'].fontName='Vera'; styles['Heading2'].fontName='VeraBold'; styles['BodyText'].fontSize=9; styles['BodyText'].leading=13; styles['BodyText'].spaceAfter=8
 styles['Heading2'].fontSize=12; styles['Heading2'].spaceBefore=13
 story=[]
 for h,t in sections:
  block=[Paragraph(escape(h),styles['Heading2'])]
  for line in t.split('\n'): block.append(Paragraph(escape(line),styles['BodyText']))
  story.append(KeepTogether(block))
 def footer(canvas,doc):
  canvas.setFont('Vera',8); canvas.setFillColor(colors.HexColor('#64748b')); canvas.drawString(42,25,'DSO 576 | Individual Coverage Cleaning'); canvas.drawRightString(553,25,str(doc.page))
 SimpleDocTemplate(str(root/'REPORT.pdf'),rightMargin=42,leftMargin=42,topMargin=36,bottomMargin=42).build(story,onFirstPage=footer,onLaterPages=footer)

if __name__=='__main__': generate()
